package com.joblens.resume;
import lombok.RequiredArgsConstructor;import org.springframework.scheduling.annotation.Async;import org.springframework.stereotype.Service;import java.util.concurrent.CompletableFuture;
@Service @RequiredArgsConstructor public class ResumeProcessingService { private final ResumeRepository resumes;private final ResumeTextExtractor extractor;private final ProfileExtractionService profiles;@Async("resumeExecutor") public CompletableFuture<Void> process(String id,byte[] bytes,String contentType,String filename){ResumeDocument r=resumes.findById(id).orElse(null);if(r==null)return CompletableFuture.completedFuture(null);try{r.setProcessingStatus("PROCESSING");resumes.save(r);String text=extractor.extract(bytes,contentType,filename).trim();if(text.isBlank())throw new IllegalArgumentException("No readable text found");r.setExtractedText(text);r.setExtractedProfile(profiles.extract(text));r.setProcessingStatus("PROFILE_EXTRACTED");r.setProcessingError(null);}catch(Exception e){r.setProcessingStatus("FAILED");r.setProcessingError(e.getMessage());}resumes.save(r);return CompletableFuture.completedFuture(null);} }
